changeSet.createProcedure:
CREATE FUNCTION public.refuse_ended_project_team_member() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    PERFORM 1 FROM public.membership m
        WHERE m.account_id = NEW.account_id AND m.workspace_id = NEW.workspace_id AND m.left_at IS NULL
        FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'a project team member needs a current workspace membership' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$

CREATE FUNCTION public.end_project_team_memberships() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    DELETE FROM public.project_team_member m
        WHERE m.account_id = NEW.account_id AND m.workspace_id = NEW.workspace_id;
    RETURN NULL;
END $$

changeSet.sql:
CREATE TRIGGER membership_end_project_teams AFTER UPDATE OF left_at ON public.membership
    FOR EACH ROW WHEN (NEW.left_at IS NOT NULL) EXECUTE FUNCTION public.end_project_team_memberships();
CREATE TRIGGER project_team_member_current BEFORE INSERT ON public.project_team_member
    FOR EACH ROW EXECUTE FUNCTION public.refuse_ended_project_team_member();
CREATE TRIGGER project_team_member_still_current AFTER UPDATE OF account_id, workspace_id ON public.project_team_member
    FOR EACH ROW EXECUTE FUNCTION public.refuse_ended_project_team_member();

changeSet.rollback:
DROP TRIGGER membership_end_project_teams ON public.membership;
DROP TRIGGER project_team_member_still_current ON public.project_team_member;
DROP TRIGGER project_team_member_current ON public.project_team_member;
DROP FUNCTION public.end_project_team_memberships();
DROP FUNCTION public.refuse_ended_project_team_member();
